import{_ as e,c as a,o as r,ae as o}from"./chunks/framework.Cthp9TdA.js";const k=JSON.parse('{"title":"Taking Care of Bun","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function i(d,t,s,l,h,p){return r(),a("div",null,t[0]||(t[0]=[o('<h1 id="taking-care-of-bun" tabindex="-1">Taking Care of Bun <a class="header-anchor" href="#taking-care-of-bun" aria-label="Permalink to &quot;Taking Care of Bun&quot;">​</a></h1><h2 id="food" tabindex="-1">Food <a class="header-anchor" href="#food" aria-label="Permalink to &quot;Food&quot;">​</a></h2><p>Bun free eats so you just have to keep the bowl of food filled up. He mainly eats at night before going to bed.</p><p>At night, add a little wet food to his regular food in order to get him to eat and you can skip having the bowl of food in the room.</p><h2 id="bathroom" tabindex="-1">Bathroom <a class="header-anchor" href="#bathroom" aria-label="Permalink to &quot;Bathroom&quot;">​</a></h2><p>He&#39;s let out to pee in the morning at 8am. He pees before bed around 11pm. He normally poops in the park in the evenings.</p><p>If he skips park or goes early, stay in the backyard till he poops. it helps to play with him by throwing the ball.</p><h2 id="trainning-for-mental-exercise" tabindex="-1"><strong>Trainning for mental exercise</strong> <a class="header-anchor" href="#trainning-for-mental-exercise" aria-label="Permalink to &quot;**Trainning for mental exercise**&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Notes</th></tr></thead><tbody><tr><td>Paw</td><td>left and right</td></tr><tr><td>Touch</td><td>place open-hand so he can bop it</td></tr><tr><td>Place</td><td>point somewhere for him to sit</td></tr><tr><td>Heel</td><td>point to your knee so he follows it</td></tr><tr><td>Grab</td><td>point to object you want him to grab like a stick</td></tr><tr><td>Wait</td><td>waits until called over and goes to you</td></tr><tr><td>Stay</td><td>stays in place and is realized when you come back to him</td></tr><tr><td>Hide &amp; Seek</td><td>use place and wait to make him stay at a spot until you hide or hide treats. Make him wait behind a door while hiding treats. May need to keep saying wait while you hide</td></tr><tr><td>Speak</td><td>bark</td></tr><tr><td>Whister</td><td>quiet growl</td></tr><tr><td>Spin</td><td></td></tr><tr><td>Rollover</td><td></td></tr><tr><td>Down</td><td></td></tr><tr><td>Sit</td><td></td></tr><tr><td>Bangbang</td><td></td></tr></tbody></table><h2 id="parks" tabindex="-1">Parks <a class="header-anchor" href="#parks" aria-label="Permalink to &quot;Parks&quot;">​</a></h2><p>Scottsdale - Chaparral Park <br><a href="https://maps.app.goo.gl/VRjzmdKLwKp664M98" target="_blank" rel="noreferrer">5401 Hayden Rd, Scottsdale, AZ 85250</a> <br> 15 - 20 mins away <br> Usually busy. Best for night or in middle of the day. Best one to come to if you have 90 mins since it&#39;s like 40 mins round trip.</p><p>Chandler - Shawnee Park <br><a href="https://maps.app.goo.gl/64D1UY5iic5WwRiW6" target="_blank" rel="noreferrer">1501 W Mesquite St, Chandler, AZ 85224</a> <br> 6 miles (15-20 mins away) <br> The most chill park. Also the biggest one. Busy around sunset. Empty once it gets dark. This one tends to be faster to get to than Scottsdale.</p><p>Tempe - Papago Bark Park <br><a href="https://maps.app.goo.gl/waJUNi9xhpFRkHzM7" target="_blank" rel="noreferrer">1000 N College Ave, Tempe, AZ 85288</a> <br> 6 miles (10-15 mins away) Only busy around sunset. It&#39;s the fastest to get to, but its the smallest. Best one to go to when limited on time, but have to go around 6:30-7:30.</p><h2 id="walks-or-hikes" tabindex="-1">Walks or Hikes <a class="header-anchor" href="#walks-or-hikes" aria-label="Permalink to &quot;Walks or Hikes&quot;">​</a></h2><p><a href="https://maps.app.goo.gl/Z9TFRofH6nVPE8236" target="_blank" rel="noreferrer">Vista Del Camino Park</a> <br> Nice nearby park to go on a walk <br> 5 miles away (15 mins away)</p><p><a href="https://maps.app.goo.gl/ZXmLr7VFjTyvNjNG7" target="_blank" rel="noreferrer">Usery Mountain Regional Park</a> <br> Desert hikes or walks <br> 18 miles away (25 mins away)</p><p><a href="https://maps.app.goo.gl/HkaLjUSjmRpdctbR7" target="_blank" rel="noreferrer">Papago preserve park</a> <br> Take the Double Butte Loop for a nice 30 mins walk. It&#39;s 15 mins away.</p><p><a href="https://maps.app.goo.gl/nhLoAh1GR2UJtVkz5" target="_blank" rel="noreferrer">Pioneer Park</a> <br> About 7 mins away. Nice for a quick quiet walk.</p><p><a href="https://maps.app.goo.gl/AwBQy1iCXkyomWnS8" target="_blank" rel="noreferrer">Pima Canyon Trailhead</a> <br> Good easy hike in South Mountain</p><p>Vets</p><p>Things to take to Mom</p><p>Paperwork</p>',22)]))}const b=e(n,[["render",i]]);export{k as __pageData,b as default};
